package dev.interview.agent.tools; import dev.interview.agent.llm.LlmClient.Action; import org.junit.jupiter.api.*; import org.junit.jupiter.api.io.TempDir; import java.nio.file.*; import java.time.Duration; import java.util.Map; import static org.assertj.core.api.Assertions.*;
class ToolExecutorTest{@TempDir Path root;ToolExecutor t=new ToolExecutor();@Test void blocksTraversal(){var r=t.execute(root,"unused",new Action("read_file",Map.of("path","../secret")),Duration.ofSeconds(1));assertThat(r.success()).isFalse();assertThat(r.output()).contains("traversal");}@Test void writesInsideWorkspace(){var r=t.execute(root,"unused",new Action("write_file",Map.of("path","a.txt","content","ok")),Duration.ofSeconds(1));assertThat(r.success()).isTrue();}}
